rios de intermediación no están incluidos.','["https://static.fotocasa.es/images/ads/b5615546-9bfb-4dc2-90a5-f2059ae10082?rule=original", "https://static.fotocasa.es/images/ads/fabb9bda-48b1-4483-bff2-cc71c36e6ecb?rule=original", "https://static.fotocasa.es/images/ads/97a6e25f-1225-4cdd-96d0-ded3460d3a08?rule=original", "https://static.fotocasa.es/images/ads/26535a69-8e76-4a46-a75b-8f926cd3330f?rule=original", "https://static.fotocasa.es/images/ads/6362e3c6-4d4f-467c-8dfd-bb24b0692854?rule=original", "https://static.fotocasa.es/images/ads/50f90c52-9923-4c76-9b91-eefcbecdb9fd?rule=original", "https://static.fotocasa.es/images/ads/a674a345-c9ca-4748-a19a-d4b28abe76ca?rule=original", "https://static.fotocasa.es/images/ads/f696f8a4-381e-4c6f-bccd-e443e83de08c?rule=original", "https://static.fotocasa.es/images/ads/3673c558-f196-4c94-a9e9-f4dac95e57b6?rule=original", "https://static.fotocasa.es/images/ads/9abe658d-b3ab-4dcb-af70-d959632e56f0?rule=original", "https://static.fotocasa.es/images/ads/6fb9e42d-03d9-4b27-8c9c-77d3fc832eb7?rule=original", "https://static.fotocasa.es/images/ads/39c52740-76ed-4753-87e7-ceb7d838514c?rule=original", "https://static.fotocasa.es/images/ads/1c3ef09b-ff01-44fe-903b-34ab8d786ad3?rule=original", "https://static.fotocasa.es/images/ads/5c6c8ff6-e3ed-433b-84ca-437a81da3ad5?rule=original", "https://static.fotocasa.es/images/ads/5a8a2025-d43b-493e-ab1a-d2d0edb0e167?rule=original"]',NULL,'[]','2026-11-20 18:08:32.186829','2026-11-20 18:08:32.186829',1);
